 ["H5", "Article covariates improve loss by < 2%", "Not supported as pre-specified (random-split E7); strict out-of-time pre-submission features supported (post hoc)", f"pre-specified E7 {pc(M['e7']['bootstrap']['rel_gain_vs_ctrl'])} [{pc(M['e7']['bootstrap']['ci_vs_ctrl'][0])}, {pc(M['e7']['bootstrap']['ci_vs_ctrl'][1])}]; strict pre-submission features {pc(a['presubmission_raw']['rel_gain_vs_control'])}; with references {pc(a['with_reference_count_demeaned']['rel_gain_vs_control'])}"],
 ["H6 (expl.)", "Drift exceeds sampling noise", "Supported", f"robust ratio {C['drift_robust']['ratio_robust_mad']:.1f}"],
 ["H7 (expl.)", "12-month window beats 24-month window", "Supported at journal level (small); not at imprint level", f"F1 − F0 {con['F1 - F0']['mean_diff']:+.4f} [{con['F1 - F0']['ci_lo']:+.4f}, {con['F1 - F0']['ci_hi']:+.4f}], Wilcoxon Holm p {con['F1 - F0']['p_holm']:.1g}; imprint t(6) CI {Z3['F1-F0']['t6_ci'][0]:+.4f} to {Z3['F1-F0']['t6_ci'][1]:+.4f}"],
 ["X1", "Received ≈ original submission (Research Square)", "Pre-set criterion not met; post-hoc statistics compatible (Springer Nature only); untestable elsewhere", f"{pc(X1sn['share_received_le_posted_plus_14'],0)} ≤ +14 d (journal-weighted {pc(Z4['journal_weighted_le14'],0)}); {pc(X1sn['share_received_gt_posted_plus_90'])} > +90 d"],
